// Window messages for Game.ProtoInput.BlockedMessages: their names (from ProtoInput's own list,
// data/window-messages.json, generated by scripts/generate-wm.mjs) and what blocking one really does.
//
// ProtoInput finds a message's "blocked" switch through a table it builds from that list
// (ProtoInputHooks/MessageList.cpp, GenerateIndexTable), reproduced here exactly:
// - a number past the end of the table: nothing happens (the log says "out of range");
// - a number missing from the list: it lands on another entry (WM_NULL, or a neighbour where the list repeats a
//   number), so blocking it switches on that entry's block instead, and every number that lands there with it.
// And messages are only blocked inside ProtoInput's message filter hook (Game.ProtoInput.MessageFilterHook).
import raw from '../../data/window-messages.json';

const ENTRIES = (raw as unknown as { entries: [number, string][] }).entries;
const INDEX: number[] = [];
ENTRIES.forEach(([id], i) => {
  for (let j = INDEX.length; j < id; j++) INDEX.push(0);
  INDEX.push(i);
});
const NAME = new Map<number, string>();
for (const [id, name] of ENTRIES) if (!NAME.has(id)) NAME.set(id, name.split(' / ')[0]);

/** The message's name, or undefined when ProtoInput doesn't list it. */
export const wmName = (id: number) => NAME.get(id);

export type BlockTarget = { kind: 'ok'; name: string } | { kind: 'other'; name: string; sharedWith: number } | { kind: 'out' };
/** What `BlockedMessages: [id]` switches on in ProtoInput. */
export function blockTarget(id: number): BlockTarget {
  if (!Number.isInteger(id) || id < 0 || id >= INDEX.length) return { kind: 'out' };
  const [eid, ename] = ENTRIES[INDEX[id]];
  if (eid === id) return { kind: 'ok', name: ename.split(' / ')[0] };
  return { kind: 'other', name: ename.split(' / ')[0], sharedWith: eid };
}

/** The ones handlers block, most used first (in Hub handlers, 2026-11-06: 270 of 600 block some), with what they mean. */
export const COMMON_MESSAGES: { id: number; name: string; meaning: string; hub: number }[] = [
  { id: 0x0008, name: 'WM_KILLFOCUS', meaning: 'The window lost keyboard focus. Blocked so a game keeps playing (and listening) when another player\'s window gets focus.', hub: 265 },
  { id: 0x02a1, name: 'WM_MOUSEHOVER', meaning: 'The mouse rested over the window. Blocked so games don\'t react to the one real cursor moving over every window.', hub: 83 },
  { id: 0x02a3, name: 'WM_MOUSELEAVE', meaning: 'The mouse left the window. Blocked so a game doesn\'t pause or drop input when the real cursor moves to another player\'s window.', hub: 82 },
  { id: 0x0006, name: 'WM_ACTIVATE', meaning: 'The window was activated or deactivated. Blocked so a game doesn\'t pause or mute when it loses the foreground.', hub: 10 },
  { id: 0x0007, name: 'WM_SETFOCUS', meaning: 'The window got keyboard focus. Rarely blocked; some games reset their input when it arrives.', hub: 1 },
  { id: 0x0086, name: 'WM_NCACTIVATE', meaning: 'The title bar is drawn as active or inactive. Blocked for games that pause on it.', hub: 1 },
  { id: 0x001c, name: 'WM_ACTIVATEAPP', meaning: 'Another program\'s window became active. Games often pause or mute on it. (Game.ProtoInput.WindowActvateAppFilter handles it too.)', hub: 0 },
  { id: 0x0021, name: 'WM_MOUSEACTIVATE', meaning: 'A click on an inactive window is about to activate it. (Game.ProtoInput.MouseActivateFilter handles it too.)', hub: 0 },
];
export const messageMeaning = (id: number) => COMMON_MESSAGES.find((m) => m.id === id)?.meaning;
export const hex = (id: number) => `0x${id.toString(16).padStart(4, '0')}`;

// ---- In the code: the numbers of a `Game.ProtoInput.BlockedMessages = [ ... ]` list, for name hints, hovers and the
//      "+" (add a message) in the editors. Text-based, so it works while the code is being typed.
export interface BlockedList { open: number; close: number; items: { start: number; end: number; id: number }[] }
export function blockedLists(text: string): BlockedList[] {
  const out: BlockedList[] = [];
  for (const m of text.matchAll(/\bProtoInput\s*\.\s*BlockedMessages\s*=\s*\[/g)) {
    const open = m.index! + m[0].length - 1;
    const close = text.indexOf(']', open);
    if (close < 0) continue;
    const body = text.slice(open + 1, close).replace(/\/\*[\s\S]*?\*\/|\/\/[^\n]*/g, (c) => ' '.repeat(c.length));
    const items = [...body.matchAll(/\b(0[xX][0-9a-fA-F]+|\d+)\b/g)].map((n) => ({ start: open + 1 + n.index!, end: open + 1 + n.index! + n[0].length, id: Number(n[1]) }));
    out.push({ open, close, items });
  }
  return out;
}
/** The list the offset is inside (between its brackets), if any. */
export const blockedListAt = (text: string, offset: number) => blockedLists(text).find((l) => offset > l.open && offset <= l.close);
/** The number at the offset in a BlockedMessages list, if any. */
export function blockedItemAt(text: string, offset: number) {
  for (const l of blockedLists(text)) for (const it of l.items) if (offset >= it.start && offset <= it.end) return it;
  return undefined;
}
/** Hover text (Markdown) for a number in a BlockedMessages list. */
export function messageMarkdown(id: number): string {
  const t = blockTarget(id), common = COMMON_MESSAGES.find((m) => m.id === id);
  const head = t.kind === 'ok' ? `**${t.name}** (${hex(id)}, ${id})` : `**${hex(id)}** (${id})`;
  const what = common ? common.meaning : t.kind === 'ok' ? 'A window message Proto Input can block.' : '';
  const hub = common?.hub ? ` Blocked by ${common.hub} of 600 Hub handlers.` : '';
  const warn = t.kind === 'out' ? 'Past the end of Proto Input\'s message list: blocking it does nothing.' : t.kind === 'other' ? `Not in Proto Input's message list: blocking it switches on the block for ${t.name} (${hex(t.sharedWith)}) instead.` : '';
  return [head, [what, hub].join('').trim(), warn, 'Blocked only with `Game.ProtoInput.MessageFilterHook = true`.'].filter(Boolean).join('\n\n');
}
/** What to insert for a message picked from the "+": the number in hex, with a comma when the list isn't empty. */
export function insertMessage(text: string, list: BlockedList, id: number): { at: number; text: string } {
  const last = list.items[list.items.length - 1];
  return last ? { at: last.end, text: `, ${hex(id)}` } : { at: list.open + 1, text: hex(id) };
}
